// Real initiative data from CS_Process_full_matrix.xlsx
// Parsed from the CSV export - ALL 267 initiatives

export interface RawInitiative {
  id: number;
  name: string;
  type: string;
  relatedIssueId: number;
  relatedIssueName: string;
  issueSeverity: number;
  issueDetected: boolean;
  prerequisites: number[];
  prerequisitesMet: boolean;
  deliveryImpact: string;
  csatImpact: string;
  businessImpact: string;
  strategicImpact: string;
  effortLevel: string;
  timelineWeeks: number | null;
}

// Parse prerequisites string like "117, 219" into number array
function parsePrerequisites(prereqStr: string): number[] {
  if (!prereqStr || prereqStr.trim() === '') return [];
  return prereqStr
    .split(',')
    .map(s => s.trim())
    .filter(s => s !== '')
    .map(s => {
      const num = parseFloat(s);
      return isNaN(num) ? null : Math.floor(num);
    })
    .filter((n): n is number => n !== null && n > 0);
}

